WITH latest_match AS (SELECT s.id, s.supplier_name, s.country, s.city, s.rating, latest.launch_date FROM suppliers s LEFT JOIN LATERAL (SELECT c.launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, supplier_name, country, city, rating, CASE WHEN country RLIKE '^(SG|JP)$' THEN 'PRIORITY' WHEN country RLIKE '^(TH|US)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS country_zone FROM latest_match ORDER BY city NULLS LAST
